CREATE TABLE "basin"."payment_authorization_operation" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "organization_id" bigint NOT NULL REFERENCES "basin"."organization"("id") ON DELETE RESTRICT,
  "expected_payment_id" bigint NOT NULL REFERENCES "basin"."expected_payment"("id") ON DELETE RESTRICT,
  "actor_member_id" bigint NOT NULL REFERENCES "basin"."organization_member"("id") ON DELETE RESTRICT,
  "idempotency_key" text NOT NULL,
  "request_hash" text NOT NULL,
  "obligation_id" text NOT NULL,
  "metadata_hash" text NOT NULL,
  "valid_until" timestamp with time zone NOT NULL,
  "status" text NOT NULL DEFAULT 'PREPARED',
  "privy_transaction_id" text,
  "transaction_hash" text,
  "failure_code" text,
  "created_at" timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at" timestamp with time zone NOT NULL DEFAULT now(),
  "completed_at" timestamp with time zone,
  CONSTRAINT "payment_authorization_operation_organization_id_idempotency_key_unique" UNIQUE("organization_id", "idempotency_key"),
  CONSTRAINT "payment_authorization_operation_expected_payment_id_unique" UNIQUE("expected_payment_id"),
  CONSTRAINT "payment_authorization_operation_request_hash" CHECK ("request_hash" ~ '^0x[0-9a-f]{64}$'),
  CONSTRAINT "payment_authorization_operation_obligation_id" CHECK ("obligation_id" ~ '^0x[0-9a-f]{64}$'),
  CONSTRAINT "payment_authorization_operation_metadata_hash" CHECK ("metadata_hash" ~ '^0x[0-9a-f]{64}$'),
  CONSTRAINT "payment_authorization_operation_transaction_hash" CHECK ("transaction_hash" IS NULL OR "transaction_hash" ~ '^0x[0-9a-f]{64}$'),
  CONSTRAINT "payment_authorization_operation_status" CHECK ("status" IN ('PREPARED','AWAITING_APPROVAL','SUBMITTED','UNKNOWN_EXTERNAL_STATE','CONFIRMED','FAILED'))
);
CREATE INDEX "payment_authorization_operation_organization_status" ON "basin"."payment_authorization_operation" ("organization_id", "status");
